#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    long n, sum = 0;
    char *endptr = NULL;

    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    for (long d = 1; d < n; ++d) {
        if (n % d == 0) sum += d;
    }

    if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else if (sum > n) {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    } else {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    }
    return 0;
}
